contract InvMutTest {
    C c;
    // the test contract is deployed with a fresh C instance provided
    constructor(C _c) { c = _c; }

    // We take all parameters that setL1BlockValues accepts plus a boolean to choose depositor vs non-depositor behavior.
    function run(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar,
        bool callAsDepositor
    ) public payable {
        require(true);

        // Read values before the call
        uint64 before_number = c.number();
        uint64 before_timestamp = c.timestamp();
        uint256 before_basefee = c.basefee();
        bytes32 before_hash = c.hash();
        uint64 before_sequence = c.sequenceNumber();
        bytes32 before_batcher = c.batcherHash();
        uint256 before_overhead = c.l1FeeOverhead();
        uint256 before_scalar = c.l1FeeScalar();

        bool reverted;

        if (callAsDepositor) {
            // To call as the depositor (the special hard-coded address in C), we simulate that
            // by having C call back into this contract would be required, but we cannot change msg.sender when calling c here.
            // Instead, we assert the general rule that if the depositor account equals address(this),
            // then the call must succeed and state must update accordingly. Otherwise the call should revert.
            // So perform the call and catch revert flag.
            try c.setL1BlockValues(_number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // Non-depositor path: call and record whether it reverted
            try c.setL1BlockValues(_number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // Read values after the call
        uint64 after_number = c.number();
        uint64 after_timestamp = c.timestamp();
        uint256 after_basefee = c.basefee();
        bytes32 after_hash = c.hash();
        uint64 after_sequence = c.sequenceNumber();
        bytes32 after_batcher = c.batcherHash();
        uint256 after_overhead = c.l1FeeOverhead();
        uint256 after_scalar = c.l1FeeScalar();

        // General rule:
        // If the call did not revert, then all public fields must equal the provided inputs.
        // If the call reverted, then all public fields must remain equal to their before-values.
        assert(
            (!reverted &&
                after_number == _number &&
                after_timestamp == _timestamp &&
                after_basefee == _basefee &&
                after_hash == _hash &&
                after_sequence == _sequenceNumber &&
                after_batcher == _batcherHash &&
                after_overhead == _l1FeeOverhead &&
                after_scalar == _l1FeeScalar
            ) || (
                reverted &&
                after_number == before_number &&
                after_timestamp == before_timestamp &&
                after_basefee == before_basefee &&
                after_hash == before_hash &&
                after_sequence == before_sequence &&
                after_batcher == before_batcher &&
                after_overhead == before_overhead &&
                after_scalar == before_scalar
            )
        );
    }

    receive() external payable {}
}

