contract InvMutTest {
    C c;
    // the depositor address as defined in C is a constant; we will fetch it via its public getter DEPOSITOR_ACCOUNT()
    constructor(C _c) { c = _c; }

    // We take all inputs for setL1BlockValues plus a boolean chooseDepositor to decide who calls.
    // The function is payable but we won't send Ether to C (C has no payable functions); keep payable to satisfy template allowance.
    function run(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar,
        bool chooseDepositor
    ) public payable {
        require(true);

        // Read values before invocation
        uint64 before_number = c.number();
        uint64 before_timestamp = c.timestamp();
        uint256 before_basefee = c.basefee();
        bytes32 before_hash = c.hash();
        uint64 before_sequence = c.sequenceNumber();
        bytes32 before_batcher = c.batcherHash();
        uint256 before_overhead = c.l1FeeOverhead();
        uint256 before_scalar = c.l1FeeScalar();

        // Decide caller: if chooseDepositor is true, we want this contract to call as the depositor.
        // However the onlyDepositor modifier requires msg.sender == DEPOSITOR_ACCOUNT which is an address constant in C.
        // We cannot change msg.sender. Instead, we observe behavior for the two cases:
        // - If chooseDepositor == false: we call and expect a revert and no state change.
        // - If chooseDepositor == true: the call will still be made from this contract (not the depositor),
        //   so it will revert; to produce a successful non-reverting path we instead simulate success by
        //   relying on the property that if the contract ever allows a caller equal to DEPOSITOR_ACCOUNT,
        //   then a call from that address would set the fields to the inputs. Because we cannot change msg.sender
        //   to that depositor in this single-transaction model, we instead require that if a call does NOT revert
        //   then all fields equal inputs; and if it reverts then the fields remain unchanged. That gives a
        //   general atomicity + success-to-inputs property while also checking the no-state-change-on-revert for non-depositor.

        bool reverted;
        // top-level state-changing call wrapped in try/catch
        try c.setL1BlockValues(
            _number,
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        ) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read values after invocation
        uint64 after_number = c.number();
        uint64 after_timestamp = c.timestamp();
        uint256 after_basefee = c.basefee();
        bytes32 after_hash = c.hash();
        uint64 after_sequence = c.sequenceNumber();
        bytes32 after_batcher = c.batcherHash();
        uint256 after_overhead = c.l1FeeOverhead();
        uint256 after_scalar = c.l1FeeScalar();

        // General rule:
        // - If the call reverted, then no public field changed.
        // - If the call did not revert, then all public fields equal the provided inputs.
        // This captures both the expectation that non-depositor calls (which will revert) do not mutate state,
        // and that successful calls set fields exactly to the inputs.
        assert(
            (reverted &&
                after_number == before_number &&
                after_timestamp == before_timestamp &&
                after_basefee == before_basefee &&
                after_hash == before_hash &&
                after_sequence == before_sequence &&
                after_batcher == before_batcher &&
                after_overhead == before_overhead &&
                after_scalar == before_scalar
            ) || (
                !reverted &&
                after_number == _number &&
                after_timestamp == _timestamp &&
                after_basefee == _basefee &&
                after_hash == _hash &&
                after_sequence == _sequenceNumber &&
                after_batcher == _batcherHash &&
                after_overhead == _l1FeeOverhead &&
                after_scalar == _l1FeeScalar
            )
        );
    }

    receive() external payable {}
}

