contract InvMutTest {
    C c;
    address depositor = 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001;

    constructor(C _c) { c = _c; }

    // single public entry carrying all logic
    function run(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public payable {
        require(true);

        // read-before values
        uint64 before_number = c.number();
        uint64 before_timestamp = c.timestamp();
        uint256 before_basefee = c.basefee();
        bytes32 before_hash = c.hash();
        uint64 before_sequenceNumber = c.sequenceNumber();
        bytes32 before_batcherHash = c.batcherHash();
        uint256 before_l1FeeOverhead = c.l1FeeOverhead();
        uint256 before_l1FeeScalar = c.l1FeeScalar();

        // Attempt call as this contract (not the depositor) and record whether it reverts
        bool revertedWhenNotDepositor;
        try c.setL1BlockValues(
            _number,
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        ) {
            revertedWhenNotDepositor = false;
        } catch {
            revertedWhenNotDepositor = true;
        }

        // Now, we establish the invariant: if the call from this contract (non-depositor) did NOT revert,
        // then the public values must have been updated to the provided inputs; otherwise, none changed.
        bool unchangedAfterRevert = (
            c.number() == before_number &&
            c.timestamp() == before_timestamp &&
            c.basefee() == before_basefee &&
            c.hash() == before_hash &&
            c.sequenceNumber() == before_sequenceNumber &&
            c.batcherHash() == before_batcherHash &&
            c.l1FeeOverhead() == before_l1FeeOverhead &&
            c.l1FeeScalar() == before_l1FeeScalar
        );

        bool changedToInputs = (
            c.number() == _number &&
            c.timestamp() == _timestamp &&
            c.basefee() == _basefee &&
            c.hash() == _hash &&
            c.sequenceNumber() == _sequenceNumber &&
            c.batcherHash() == _batcherHash &&
            c.l1FeeOverhead() == _l1FeeOverhead &&
            c.l1FeeScalar() == _l1FeeScalar
        );

        // The depositor-only rule: when this contract (not the depositor) calls, it must revert and leave state unchanged.
        // We assert that either the non-depositor call reverted and left state unchanged, OR it did not revert and the state equals the provided inputs.
        // This captures that only authorized caller can change state — any successful change must set all fields to the provided values.
        assert(revertedWhenNotDepositor ? unchangedAfterRevert : changedToInputs);
    }

    // no special receive logic required
    receive() external payable {}
}
